// Builds single-file SQL bundles for pasting into the Supabase SQL Editor.
//   supabase/all_migrations.sql      = every migration in order (safe on a freshly reset schema)
//   supabase/reset_and_migrate.sql   = DESTRUCTIVE reset of `public` + every migration
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const dir = path.join(root, "supabase/migrations");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const header = (title) => `-- ${title}\n-- Generated by scripts/db-bundle.mjs — edit the files in supabase/migrations instead.\n\n`;
const body = files.map((f) => `-- ===== ${f} =====\n${fs.readFileSync(path.join(dir, f), "utf8")}\n`).join("\n");

fs.writeFileSync(path.join(root, "supabase/all_migrations.sql"), header("mmbookhouse — all migrations") + body);
const reset = fs.readFileSync(path.join(root, "supabase/reset_public_schema.sql"), "utf8");
fs.writeFileSync(path.join(root, "supabase/reset_and_migrate.sql"), header("mmbookhouse — RESET public schema + all migrations (DESTRUCTIVE)") + reset + "\n" + body);
console.log(`Bundled ${files.length} migrations.`);
